/* ── ASIDE CARDS ── */
.leb-b3__aside-card { background: #FFFFFF; border: 1px solid rgba(11,26,46,0.07); border-radius: 4px; padding: 1.4rem; display: flex; flex-direction: column; gap: 0.75rem; }
